    this.modStage = ENV_IDLE;
    this.modLevel = 0;
    this.modTime = 0;
    this.delayModEnv = 0;
    this.attackModEnv = 0.001;
    this.holdModEnv = 0;
    this.decayModEnv = 0.01;
    this.sustainModEnv = 0;
